"use strict";

const fs = require("node:fs");
const path = require("node:path");

const projectRoot = path.resolve(__dirname, "../..");
const assetsRoot = path.join(projectRoot, "public/assets/js");

function read(relativePath) {
  const absolutePath = path.join(assetsRoot, relativePath);
  return `/* --- ${relativePath} --- */\n${fs.readFileSync(absolutePath, "utf8").trim()}\n`;
}

function writeBundle(outputPath, sources) {
  const contents = [
    "/* This file is generated by src/scripts/buildClientBundles.js. */",
    "/* Edit the source modules listed below, then run npm run build:client. */",
    ...sources.map(read),
    "",
  ].join("\n\n");

  const absoluteOutputPath = path.join(assetsRoot, outputPath);
  fs.mkdirSync(path.dirname(absoluteOutputPath), { recursive: true });
  fs.writeFileSync(absoluteOutputPath, contents);
}

// Os módulos administrativos são carregados pelo bootstrap público em ordem.
// Não os concatene: cada arquivo deve permanecer auditável e abaixo do limite.

for (const page of ["profile", "punch", "report"]) {
  writeBundle(`employee/${page}.js`, [
    "shared/loading.js",
    "employee/modules/shared.js",
    `employee/modules/${page}.js`,
  ]);
}

writeBundle("auth/login.js", ["shared/loading.js", "auth/modules/login.js"]);
writeBundle("auth/password-recovery.js", ["auth/modules/password-recovery.js"]);
writeBundle("auth/password.js", ["auth/modules/password.js"]);
writeBundle("auth/first-access.js", ["shared/loading.js", "auth/modules/first-access.js"]);
writeBundle("auth/first-access.js", ["shared/loading.js", "auth/modules/first-access.js"]);

// CSS é servido por manifestos @import em public/assets/css/bundles.
// Isso mantém a organização por responsabilidade sem recriar arquivos grandes.
console.log("Client JavaScript bundles built successfully; CSS uses public manifests.");
